/* Expectation: signed mass accumulation, outcome-wise algebra, counts, tails and loss. */
(() => {
'use strict';
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cp=x=>JSON.parse(JSON.stringify(x)),sum=a=>a.reduce((s,x)=>s+x,0),fmt=x=>Number.isInteger(x)?String(x):Number(x.toFixed(6)).toString();
const math=s=>'<math xmlns="http://www.w3.org/1998/Math/MathML"><mrow>'+String(s).split(/([=+−×÷≤≥<>(),;])/).filter(Boolean).map(t=>/^[=+−×÷≤≥<>(),;]$/.test(t)?'<mo>'+esc(t)+'</mo>':/^\s*-?\d+(\.\d+)?\s*$/.test(t)?'<mn>'+t.trim()+'</mn>':'<mtext>'+esc(t)+'</mtext>').join('')+'</mrow></math>';
const txt=(x,y,s,cls='label',anchor='start')=>`<text x="${x}" y="${y}" text-anchor="${anchor}" class="exp-${cls}">${esc(s)}</text>`;
const line=(x,y,u,v,c='#7d96a1')=>`<line x1="${x}" y1="${y}" x2="${u}" y2="${v}" stroke="${c}" stroke-width="2"/>`;
const box=(x,y,w,h,c='#e2eee8')=>`<polygon points="${x},${y} ${x+w},${y} ${x+w},${y+h} ${x},${y+h}" fill="${c}" stroke="#8ba8ac"/>`;
const wrap=(s,h=470)=>`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 ${h}" role="img" data-visual-type="plot">${s}</svg>`;
const dot=(x,y,id,c='#a47145',r=8)=>`<g data-entity="${esc(id)}"><circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/></g>`;
const diff=(a,b,p='')=>JSON.stringify(a)===JSON.stringify(b)?[]:a&&b&&typeof a==='object'&&typeof b==='object'?[...new Set([...Object.keys(a),...Object.keys(b)])].flatMap(k=>diff(a[k],b[k],p?p+'.'+k:k)):[{field:p,before:a??null,after:b??null}];
const make=(id,title,kind,invariant,code)=>({id,title,kind,invariant,code,frames:[]});
function frame(m,state,svg,operation,why,checks=[],formula='',active=0){const snapshot=cp(state),prev=m.frames.at(-1)?.snapshot;m.frames.push({snapshot,svg,caption:why,formulaHtml:formula?math(formula):'',teaching:{operation,why,checks:checks.map(([s,r])=>({mathHtml:math(s),result:String(r)})),changes:prev?diff(prev,snapshot):[],currentState:snapshot,initial:!prev,reading:m.invariant,guide:m.code,activeLine:active,mode:m.kind}});}
function law(v,p){if(v.length!==p.length||!v.length||v.some(x=>!Number.isFinite(x))||p.some(x=>!Number.isFinite(x)||x<0)||Math.abs(sum(p)-1)>1e-9)throw Error('Use finite values and nonnegative masses of equal length, summing to one.');return v.map((x,i)=>({x,p:p[i]}));}
function weighted(v,p,g=x=>x,id='mean',title='Signed mean: accumulate value times probability'){
 const a=law(v,p),z=a.map(r=>g(r.x));if(z.some(x=>!Number.isFinite(x)))throw Error('The transformed values must be finite.');const mu=sum(z.map((x,i)=>x*p[i])),m=make(id,title,'signed-weighted-balance','The numeric coordinate axis remains fixed. Green marks probability weights; gold marks the accumulated signed contribution, not a conditional mean.',['Read one supplied atom and its probability.','Apply the specified measurement to that atom.','Multiply transformed value by its original probability.','Add the signed contribution to the accumulator.']);const lo=Math.min(0,...z,mu)-1,hi=Math.max(0,...z,mu)+1,x=t=>110+780*(t-lo)/(hi-lo);let acc=0;
 const draw=k=>{let s=txt(35,30,title)+line(110,245,890,245);for(let i=0;i<a.length;i++){const rank=z.slice(0,i).filter(t=>Math.abs(x(t)-x(z[i]))<38).length;if(!rank)s+=line(x(z[i]),239,x(z[i]),251)+txt(x(z[i]),281,fmt(z[i]),'math','middle');s+=dot(x(z[i]),90+rank*32,'mass-'+i,i===k?'#a47145':'#4f8a78',7+10*Math.sqrt(p[i]));s+=box(70,320+i*62,850,46,i===k?'#f0dfbc':'#e9f0f1')+txt(92,350+i*62,`x = ${fmt(v[i])}; g(x) = ${fmt(z[i])}; mass = ${fmt(p[i])}; contribution = ${fmt(z[i]*p[i])}`,'math');}s+=dot(x(acc),245,'accumulator')+txt(35,325+a.length*62,'Signed accumulator = '+fmt(acc)+'; complete mean = '+fmt(mu),'math');return wrap(s,370+a.length*62);};
 frame(m,{values:v,masses:p,transformed:z,contributions:z.map((x,i)=>x*p[i]),k:-1,acc:0,mu},draw(-1),'Initialize the signed accumulator','A partial signed contribution is not a normalized expectation. The complete probability weights stay visible.');a.forEach((r,i)=>{acc+=z[i]*r.p;frame(m,{values:v,masses:p,transformed:z,contributions:z.map((x,i)=>x*p[i]),k:i,acc,mu},draw(i),'Multiply and add one atom contribution','Use the transformed measurement at this atom and its original mass. Negative contributions move the accumulator left.',[['mass ≥ 0',r.p>=0],['partial sum equals processed contributions',Math.abs(acc-sum(z.slice(0,i+1).map((x,j)=>x*p[j])))<1e-10]],'partial contribution = '+fmt(acc),3);});m.result={mean:mu,contributions:z.map((x,i)=>x*p[i]),transformed:z};return m;
}
function heavy(signed=false,id='heavy'){
 const m=make(id,signed?'Symmetric truncation: zero signed prefix, divergent absolute prefix':'Heavy tail: probability shrinks, mean contribution stays constant','integrability-tail-test','Each displayed k is an exponent index, not a numeric X axis. The undisplayed tail mass is explicit. Finite checkpoints do not prove an infinite limit; the symbolic series in the lesson does.',['Include one positive magnitude 2^k.','Assign the original geometric probability.','Track signed, positive, negative and absolute contributions separately.','Retain the omitted mass and the infinite-tail conclusion.']);for(let r=1;r<=7;r++){let s=txt(35,30,'Unconditioned infinite law: inspect a prefix, never renormalize it');for(let k=1;k<=7;k++){s+=txt(80+k*110,94,'k = '+k,'math','middle')+box(35+k*110,130,90,150*(signed?1:1),'#dceae3')+txt(80+k*110,310,k<=r?'included':'tail','label','middle');}s+=txt(60,360,`Omitted probability = ${fmt(2**-r)}; absolute prefix mean = ${r}`,'math')+txt(60,407,signed?'Positive and negative prefix means are r/2; both diverge.':'Every mean term is 1; an arbitrarily small tail still has infinite mean.');s+=line(140,475,840,475)+dot(140+100*r,475,'absolute-prefix')+txt(60,455,'Absolute prefix moment: fixed scale 0–7')+line(140,565,840,565)+dot(140+700*2**-r,565,'tail-mass','#4f8a78')+txt(60,540,'Omitted probability: fixed scale 0–1');frame(m,{r,tail:2**-r,positive:signed?r/2:r,negative:signed?r/2:0,absolute:r,signedPrefix:signed?0:r},wrap(s,620),'Extend the original-law prefix','Increasing the prefix shrinks missing probability while adding a nonvanishing moment term. The missing mean is never certified by the missing probability alone.',[['tail mass > 0',2**-r>0],['absolute prefix grows with r',r===m.frames.length+1]],'absolute prefix mean = '+r,3);}m.result=m.frames.at(-1).snapshot;return m;
}
function dependent(id='linear-dependent'){
 const m=make(id,'Linearity works on the same outcome; products retain dependence','outcome-wise-linearity','Rows are the two original outcomes with mass one half each. The displayed sum uses the same row values, never independently resampled variables.',['Read X and Y on one common outcome.','Compute 3X − 2Y + 5 pointwise.','Weight that sum by the outcome probability.','Contrast the actual XY with the product of separate means.']);const rows=[{x:-1,y:1,p:.5},{x:1,y:-1,p:.5}];let total=0;for(let k=-1;k<2;k++){if(k>=0)total+=(3*rows[k].x-2*rows[k].y+5)*.5;let s=txt(35,30,'Perfect dependence: Y = −X')+txt(90,105,'outcome','label')+txt(300,105,'X','math')+txt(440,105,'Y','math')+txt(600,105,'3X − 2Y + 5','math')+txt(850,105,'XY','math');rows.forEach((r,i)=>{s+=box(60,140+i*90,870,60,i===k?'#efdbb6':'#e6efec')+txt(90,180+i*90,'row '+(i+1))+txt(300,180+i*90,r.x,'math')+txt(440,180+i*90,r.y,'math')+txt(660,180+i*90,3*r.x-2*r.y+5,'math')+txt(850,180+i*90,r.x*r.y,'math');});s+=txt(60,380,'Weighted sum accumulator = '+fmt(total)+'; product mean = −1','math');frame(m,{rows,k,total,sumMean:5,productMean:-1},wrap(s),'Average a common-outcome sum','The sum mean equals 3E[X] − 2E[Y] + 5, while the product mean differs from E[X]E[Y].',[['Y = −X in every row',rows.every(r=>r.y===-r.x)]],'mean of the affine sum = 5',k<0?0:2);}m.result={sumMean:5,productMean:-1};return m;
}
function fixed(n=4,id='fixed-four'){
 const m=make(id,'Fixed points: a permutation realization and its indicator probabilities','permutation-match-count','Top positions and bottom target labels stay fixed. Connected arrows show one permutation, not its expected count. Each marginal match probability is 1/n.',['Display a valid bijection.','Compare the target image with its position.','Count matches in this realization.','Separately sum the n probabilities 1/n.']);const perms=[Array.from({length:n},(_,i)=>i),Array.from({length:n},(_,i)=>(i+1)%n),n===4?[0,2,1,3]:Array.from({length:n},(_,i)=>n-1-i)];for(const perm of perms){let s=txt(35,30,'One bijection; expected count is averaged over all uniform permutations');perm.forEach((j,i)=>{const x=110+i*180,z=110+j*180;s+=box(x,85,130,50,i===j?'#efdbb6':'#e6efec')+box(z,285,130,50,'#e6efec')+txt(x+65,117,'position '+(i+1),'label','middle')+txt(z+65,317,'label '+(j+1),'label','middle')+`<path d="M ${x+65} 135 C ${x+65} 195, ${z+65} 225, ${z+65} 285" fill="none" stroke="#668896" stroke-width="2"/>`+`<polygon points="${z+65},285 ${z+60},275 ${z+70},275" fill="#668896"/>`;});const realized=perm.filter((v,i)=>v===i).length;s+=txt(60,400,'Realized matches = '+realized+'; mean over all permutations = 1','math');frame(m,{n,perm,realized,indicatorMeans:Array(n).fill(1/n),expected:1},wrap(s),'Inspect a different valid permutation','A realization can have zero, two, or four matches here, while the full uniform mean remains one.',[['bijection uses every label once',new Set(perm).size===n],['sum of match probabilities = 1',Math.abs(n*(1/n)-1)<1e-12]],'expected matches = 1',3);}m.result={expected:1};return m;
}
function records(values=[4,2,5,1,3],id='record-five'){
 const n=values.length,m=make(id,'Running minimum: tests, successful updates, and record probabilities','running-record-algorithm','The slots remain fixed; a scanner advances across the actual array. The trace count is one realization, while the harmonic mean averages all uniform permutations.',['Initialize minimum to positive infinity.','Read the next fixed array position.','Update only when its value is smaller.','Advance scanner; sum record probabilities separately.']);let best=null,updates=0;for(let i=-1;i<n;i++){const changed=i>=0&&(best===null||values[i]<best);if(changed){best=values[i];updates++;}let s=txt(35,30,'One realization of a uniform-permutation input');values.forEach((v,j)=>s+=box(110+j*150,110,105,75,j===i?'#efdbb6':'#e6efec')+txt(162+j*150,158,v,'math','middle')+txt(162+j*150,222,'i = '+(j+1),'math','middle'));s+=dot(162+Math.max(0,i)*150,260,'scanner')+txt(60,330,'Current minimum = '+(best===null?'not set':best)+'; realized updates = '+updates,'math')+txt(60,385,'Expected total = 1 + 1/2 + … + 1/n; loop tests = n','math');frame(m,{values,i,best,changed,updates,tests:i+1,recordProbability:i<0?null:1/(i+1),expected:sum(values.map((_,j)=>1/(j+1)))},wrap(s),i<0?'Initialize scanner':changed?'Update the current minimum':'Keep the previous minimum',i<0?'No value has been read.':changed?'This value beats the minimum of all earlier values.':'This value is not a new minimum. A comparison still occurred.',i<0?[]:[['minimum equals processed prefix minimum',best===Math.min(...values.slice(0,i+1))],['update condition',changed]],'realized updates = '+updates,i<0?0:changed?2:3);}m.result=m.frames.at(-1).snapshot;return m;
}
function bins(m=4,p=[1/3,1/3,1/3],id='bins-four'){
 const n=p.length;if(p.some(x=>x<0)||Math.abs(sum(p)-1)>1e-9)throw Error('Bin probabilities must sum to one.');const model=make(id,'Occupancy: sample placements versus mean occupied bins','occupancy-ball-placement','A sample path moves identifiable balls into fixed bins. Expected occupied/empty counts are calculated separately from avoidance probabilities, not inferred from this single sample.',['Start with empty fixed bins.','Move one identified ball into its displayed destination.','Count occupied bins and unordered collisions in this path.','Compare with the exact expectation formulas.']);const locations=Array.from({length:m},(_,i)=>i===m-1?0:i%n),counts=Array(n).fill(0),emptyMean=sum(p.map(q=>(1-q)**m)),collisionMean=m*(m-1)/2*sum(p.map(q=>q*q));
 for(let step=0;step<=m;step++){if(step)counts[locations[step-1]]++;let s=txt(35,30,`Independent allocations: ${m} balls; probabilities ${p.map(fmt).join(', ')}`);for(let j=0;j<n;j++){s+=box(100+j*260,150,205,180,'#e6efec')+txt(202+j*260,130,'bin '+(j+1),'label','middle')+txt(202+j*260,370,'count = '+counts[j],'math','middle');}for(let i=0;i<m;i++){const dest=locations[i],rank=locations.slice(0,i+1).filter(x=>x===dest).length-1;s+=dot(i<step?135+dest*260+(rank%3)*48:130+i*75,i<step?195+Math.floor(rank/3)*46:75,'ball-'+i,'#ad7849',10);}const occupied=counts.filter(x=>x>0).length,collisions=sum(counts.map(c=>c*(c-1)/2));s+=txt(60,415,`Realized occupied = ${occupied}; pair collisions = ${collisions}`,'math')+txt(60,455,`Full-horizon means: occupied = ${fmt(n-emptyMean)}; collisions = ${fmt(collisionMean)}`,'math');frame(model,{m,p,locations,step,counts,occupied,collisions,emptyMean,occupiedMean:n-emptyMean,collisionMean},wrap(s,500),step?'Place the next identified ball':'Initialize unallocated balls','The destination shows one possible path. Every mean is separately derived from the stated full-horizon probability model.',[['processed balls = sum of occupancies',sum(counts)===step],['nonnegative counts',counts.every(c=>c>=0)]],'expected occupied bins = '+fmt(n-emptyMean),step?2:0);}model.result=model.frames.at(-1).snapshot;return model;
}
function tails(v,p,id='tail-main',second=false){law(v,p);if(v.some(x=>!Number.isInteger(x)||x<0||x>8))throw Error('Tail laboratory uses integer values from 0 to 8.');const H=Math.max(...v),baseline=120+Math.max(H,1)*55,m=make(id,second?'Squared heights: odd increments weight each survival layer':'Layer cake: one level for every reached integer threshold','integer-tail-layer-cake','Columns denote the original outcomes, and layer widths denote their probabilities. Highlighting threshold k selects the event N ≥ k. No PMF is renormalized.',['Draw the nonnegative integer heights with their masses.','Select every column reaching threshold k.','Sum that event probability.','Add its contribution, with odd weight for the second moment.']);let total=0;for(let k=0;k<=H;k++){const tail=k?sum(p.filter((_,i)=>v[i]>=k)):0,weight=second?2*k-1:1;if(k)total+=tail*weight;let s=txt(35,30,second?'Second moment uses layer weight 2k − 1':'First moment adds unweighted survival probabilities');v.forEach((val,i)=>{const x=100+i*190;for(let j=1;j<=val;j++)s+=box(x+65-(130*p[i]/Math.max(...p))/2,baseline-j*55,130*p[i]/Math.max(...p),46,j===k?'#efdbb6':'#e1ece8');s+=txt(x+65,baseline+37,'N = '+val,'math','middle')+txt(x+65,baseline+75,'mass '+fmt(p[i]),'math','middle');});s+=txt(60,baseline+125,`k = ${k}; survival = ${fmt(tail)}; accumulated moment = ${fmt(total)}`,'math');frame(m,{v,p,k,tail,weight,second,total},wrap(s,baseline+165),k?'Add the next survival layer':'Inspect the original heights',k?'The highlighted blocks correspond exactly to outcomes reaching this threshold.':'A zero height contributes no positive layer.',[['tail equals selected original masses',Math.abs(tail-(k?sum(p.filter((_,i)=>v[i]>=k)):0))<1e-12]],'accumulated moment = '+fmt(total),k?3:0);}m.result={mean:total};return m;}
function capped(p=.25,r=3,id='cap-three'){if(p<0||p>1||!Number.isInteger(r)||r<1||r>10)throw Error('Use success probability in [0,1] and integer cap 1–10.');const q=1-p,m=make(id,'Capped trials: surviving paths execute the next trial','capped-waiting-survival','Every horizontal row is a fixed trial index. The bar length is the probability that this trial is executed, including paths that eventually fail at the cap.',['Trial one is executed on every path.','Reach trial k only after k−1 failures.','Add the execution probabilities.','Keep terminal no-success paths at the cap.']);let total=0;for(let k=0;k<=r;k++){if(k)total+=q**(k-1);let s=txt(35,30,'Execution probabilities, not success-time probabilities');for(let j=1;j<=r;j++)s+=txt(70,100+j*38,'trial '+j)+box(160,75+j*38,670*q**(j-1),25,j<=k?'#d5e8df':'#e9eff1')+txt(860,95+j*38,fmt(q**(j-1)),'math');s+=txt(60,150+r*38,`accumulated executed-trial mean = ${fmt(total)}; no-success mass = ${fmt(q**r)}`,'math');frame(m,{p,r,k,tail:q**r,total,execution: Array.from({length:r},(_,j)=>q**j)},wrap(s,210+r*38),k?'Include another possible executed trial':'Initialize the fixed cap','Executed counts include no-success paths; a failure return code or a success-conditioned measurement would use different weights.',[['mean prefix ≤ cap',total<=r+1e-10]],'expected executed trials = '+fmt(total),k?2:0);}m.result={mean:total,noSuccess:q**r};return m;}
function loss(v,p,id='loss-main'){const a=law(v,p),mu=sum(a.map(r=>r.x*r.p)),variance=sum(a.map(r=>(r.x-mu)**2*r.p)),L=Math.min(...v)-1,H=Math.max(...v)+1,x=c=>100+800*(c-L)/(H-L),max=variance+Math.max((L-mu)**2,(H-mu)**2),y=c=>350-250*(variance+(c-mu)**2)/max,m=make(id,'Squared-loss prediction: move a constant on a fixed parabola','least-squares-loss','The horizontal coordinate is the proposed constant c, not an observed X. The vertical coordinate is its expected squared loss. The curve and mean remain fixed.',['Compute the distribution mean and variance.','Choose a proposed constant prediction.','Evaluate variance + squared distance from the mean.','Move to the unique continuous optimum.']);const curve=Array.from({length:101},(_,i)=>{const c=L+(H-L)*i/100;return x(c)+','+y(c);}).join(' ');for(const c of [L,(L+mu)/2,mu,H]){const value=variance+(c-mu)**2;let s=txt(35,30,'Constant prediction and its expected squared error')+line(100,350,900,350)+line(100,90,100,350)+`<polyline points="${curve}" fill="none" stroke="#4e8593" stroke-width="3"/>`+dot(x(c),y(c),'prediction')+txt(500,402,'Proposed prediction c; mean = '+fmt(mu),'math','middle')+txt(60,450,'c = '+fmt(c)+'; expected squared loss = '+fmt(value),'math');for(const t of [L,mu,H])s+=txt(x(t),380,fmt(t),'math','middle');frame(m,{v,p,mu,variance,c,loss:value},wrap(s,490),'Change the constant prediction','Only the proposal moves. The excess over minimum loss is exactly its squared distance from the mean.',[['loss ≥ variance',value>=variance-1e-10],['current prediction attains minimum',Math.abs(value-variance)<1e-10]],'loss = '+fmt(variance)+' + ('+fmt(c)+' − '+fmt(mu)+')²',2);}m.result={mean:mu,variance};return m;}
function graph(id='graph-five'){const n=5,p=.5,edges=[];for(let i=0;i<n;i++)for(let j=i+1;j<n;j++)edges.push([i,j]);const m=make(id,'Graph indicators: a selected edge or triangle uses specific vertices','graph-edge-and-triangle-count','Vertex positions never move. Actual edges meet circle boundaries. A highlighted triangle requires its three specified edges; the mean averages all graph realizations.',['List every possible unordered vertex pair.','Select one edge indicator of mean p.','Select a vertex triple and its three required edges.','Sum the edge and triangle probabilities separately.']);const pos=Array.from({length:n},(_,i)=>[500+220*Math.cos(-Math.PI/2+i*2*Math.PI/n),275+185*Math.sin(-Math.PI/2+i*2*Math.PI/n)]);for(let step=0;step<3;step++){let s=txt(35,30,['All possible edge slots','One selected edge indicator','One selected triangle indicator'][step]);for(const [i,j] of edges){const a=pos[i],b=pos[j],dx=b[0]-a[0],dy=b[1]-a[1],len=Math.hypot(dx,dy),hit=step===1?i===0&&j===1:step===2?i<3&&j<3:false;s+=line(a[0]+dx*23/len,a[1]+dy*23/len,b[0]-dx*23/len,b[1]-dy*23/len,hit?'#a47145':'#d4dee2');}pos.forEach(([x,y],i)=>s+=`<circle cx="${x}" cy="${y}" r="23" fill="#e4eeea" stroke="#6c9094"/>`+txt(x,y+6,i+1,'math','middle'));s+=txt(60,510,'Expected edges = 5; expected triangles = 1.25','math');frame(m,{n,p,edges,step,selected:step===1?[[0,1]]:step===2?[[0,1],[0,2],[1,2]]:[],edgeMean:5,triangleMean:1.25},wrap(s,550),'Select the exact required edge set','Independent edge presence gives p for one edge and p³ for a triangle. Triangle indicators may still depend on one another.',[['possible pair count = 10',edges.length===10]],'triangle probability = '+fmt(p**3),step);}m.result={edgeMean:5,triangleMean:1.25};return m;}
function windows(id='window-eight'){const bits=[1,1,1,1,0,1,1,1],n=bits.length,r=3,m=make(id,'Overlapping windows: slide the start, preserve bit identities','overlapping-success-windows','Eight fixed bit slots are one realization. A window moves across six valid starts. It counts every qualifying start, including overlaps.',['Keep the original bits in fixed slots.','Move the length-three window by one start.','Test whether all three enclosed bits equal one.','Add a realized indicator; retain its full-law probability 1/8.']);let count=0;for(let k=0;k<=n-r;k++){const hit=bits.slice(k,k+r).every(x=>x===1);if(hit)count++;let s=txt(35,30,'One realization; six potential windows under fair independent bits');bits.forEach((b,i)=>s+=box(100+i*100,140,75,65,'#e4eeea')+txt(137+i*100,181,b,'math','middle'));s+=`<g data-entity="window"><polygon points="${90+k*100},125 ${390+k*100},125 ${390+k*100},220 ${90+k*100},220" fill="none" stroke="#a47145" stroke-width="3"/></g>`+txt(60,290,`start = ${k+1}; all heads = ${hit}; realized window count so far = ${count}`)+txt(60,350,'Full-horizon expected window count = 6/8 = 0.75','math');frame(m,{bits,k,r,hit,count,probability:1/8,expected:.75},wrap(s,410),'Shift and evaluate the next overlapping window','The enclosed bits determine this realization indicator. Overlapping windows are not independent, but their means add.',[['all enclosed bits equal 1',hit]],'mean contribution per start = 1/8',2);}m.result={realized:count,expected:.75};return m;}
function fixtures(){const groups={},models=[],add=(g,m)=>{(groups[g]??=[]).push(m.id);models.push(m);};
 add('mean',weighted([-2,1,4],[.2,.5,.3],x=>x,'mean-main'));
 add('mean',weighted([-2,1,4],[.2,.5,.3],x=>Math.abs(x),'absolute-main','Absolute mean: remove sign before multiplying'));
 add('existence',heavy(false,'heavy-positive'));add('existence',heavy(true,'heavy-signed'));
 add('lotus',weighted([-2,1,4],[.2,.5,.3],x=>x*x,'square-main','LOTUS: square each value before averaging'));
 add('lotus',weighted([-2,-1,0,1,2],[.1,.2,.2,.2,.3],x=>x*x,'square-symmetric','Many-to-one square: each original mass contributes once'));
 add('linearity',dependent());add('permutations',fixed());add('records',records());
 add('occupancy',bins());add('occupancy',bins(2,[.5,1/3,1/6],'bins-nonuniform'));
 add('tails',tails([0,1,2,3],[.25,.25,.25,.25]));add('tails',tails([0,1,2,3],[.25,.25,.25,.25],'tail-second',true));
 add('waiting',capped());add('moments',weighted([0,2,4],[.25,.5,.25],x=>(x-2)**2,'central-four','Central moment: square the distance from the fixed mean'));
 add('loss',loss([-2,1,4],[.2,.5,.3]));add('problem-only',weighted([-2,1,4],[.2,.5,.3],x=>Math.max(x-1,0),'clip-main','Threshold payoff: transform before averaging'));
 add('problem-only',graph());add('problem-only',windows());
 return {topicId:'s_expectation',groups,models};}
const api={weighted,heavy,dependent,fixed,records,bins,tails,capped,loss,graph,windows,law,fixtures};
if(typeof module!=='undefined'){module.exports=api;return;}globalThis.ExpectationModels=api;
const controls=()=>'<div class="exp-controls"><button type="button" data-reset>Restart</button><button type="button" data-prev>Previous</button><button type="button" data-play>Play</button><button type="button" data-next>Next</button><label>Speed<select data-speed><option value="2600">Slow</option><option value="1800" selected>Normal</option><option value="1300">Fast</option></select></label><label>Step<input type="range" data-seek min="0" value="0"></label></div><div class="exp-stage"></div><p class="exp-caption"></p><p data-progress></p><div class="exp-formula formula-block"></div><div class="exp-print"></div>';
function mount(host,m){return AdvancedSimulations.mount(host,m,{topic:"s_expectation",prefix:"exp"});}
async function boot(){const data=await(await fetch('s_expectation-models.json')).json();globalThis.ExpectationPlayers=[];for(const h of document.querySelectorAll('[data-exp-model]')){const m=data.models.find(m=>m.id===h.dataset.expModel);if(!m)throw Error('Missing expectation model');ExpectationPlayers.push(mount(h,m));}const form=document.querySelector('#exp-form'),output=document.querySelector('#exp-output'),error=document.querySelector('#exp-error');let current=null;
const numbers=s=>{const parts=String(s).split(',').map(x=>x.trim());if(!parts.length||parts.some(x=>!/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(x)))throw Error('Use comma-separated finite numbers with no empty fields.');const a=parts.map(Number);if(a.length>5||a.some(x=>!Number.isFinite(x)||Math.abs(x)>100))throw Error('Use 1–5 values between −100 and 100.');return a;};
form.addEventListener('submit',e=>{e.preventDefault();try{const fd=new FormData(form),kind=fd.get('kind'),v=numbers(fd.get('values')),p=numbers(fd.get('masses'));let m;
 if(['mean','square','absolute','loss','tails'].includes(kind)){law(v,p);m=kind==='loss'?loss(v,p,'editable'):kind==='tails'?tails(v,p,'editable'):weighted(v,p,kind==='square'?x=>x*x:kind==='absolute'?x=>Math.abs(x):x=>x,'editable');}
 else {const cap=Number(fd.get('cap')),prob=Number(fd.get('prob'));if(!String(fd.get('cap')).trim()||!String(fd.get('prob')).trim()||!Number.isFinite(cap)||!Number.isFinite(prob))throw Error('Parameters must be finite, nonempty numbers.');if(kind==='cap')m=capped(prob,cap,'editable');else if(kind==='bins'){if(!Number.isInteger(cap)||cap<0||cap>8||!Number.isInteger(prob)||prob<1||prob>3)throw Error('Occupancy needs 0–8 balls and 1–3 uniform bins.');m=bins(cap,Array(prob).fill(1/prob),'editable');}else throw Error('Select a valid laboratory mode.');}
 current?.dispose();output.innerHTML='<section class="exp-model" tabindex="0"><h3>'+esc(m.title)+'</h3><p>'+esc(m.invariant)+'</p>'+controls()+'</section>';current=mount(output.firstChild,m);globalThis.ExpectationLab=current;error.textContent='';}catch(err){error.textContent=err.message;}});
}
boot().catch(err=>{console.error(err);document.querySelector('#exp-error').textContent='The expectation models could not load. Reload the chapter to retry.';});
})();
